import SwiftUI
import UniformTypeIdentifiers
struct MainView:View{@ObservedObject var model:ConverterModel;@State private var targeted=false;var body:some View{VStack(spacing:18){HStack{Image(systemName:"leaf.fill").font(.system(size:28,weight:.semibold)).foregroundStyle(.tint);VStack(alignment:.leading){Text("l’orangerie").font(.largeTitle.bold());Text("Ferramentas de arquivos, privadas e locais").foregroundStyle(.secondary)};Spacer();Button("Adicionar imagens"){model.chooseFiles()}.buttonStyle(.borderedProminent)};VStack(spacing:10){Image(systemName:"square.and.arrow.down").font(.system(size:34));Text("Arraste imagens para cá").font(.title3.weight(.semibold));Text("Tudo é processado no seu Mac — sem envio de arquivos").font(.callout).foregroundStyle(.secondary)}.frame(maxWidth:.infinity).frame(height:140).background(targeted ? Color.accentColor.opacity(0.12):Color.secondary.opacity(0.06)).clipShape(RoundedRectangle(cornerRadius:16)).overlay(RoundedRectangle(cornerRadius:16).strokeBorder(style:StrokeStyle(lineWidth:1,dash:[6,4])).foregroundStyle(.secondary.opacity(0.4))).onDrop(of:[UTType.fileURL],isTargeted:$targeted){ps in let g=DispatchGroup();var u:[URL]=[];for p in ps{g.enter();_ = p.loadObject(ofClass:URL.self){x,_ in if let x{u.append(x)};g.leave()}};g.notify(queue:.main){model.add(urls:u)};return true};GroupBox("Saída"){VStack(spacing:14){HStack{Text("Formato");Picker("Formato",selection:$model.outputFormat){ForEach(OutputFormat.allCases){Text($0.rawValue).tag($0)}}.labelsHidden().frame(width:130);Spacer();Text("Qualidade JPEG");Slider(value:$model.jpegQuality,in:0.2...1,step:0.05).frame(width:130).disabled(model.outputFormat != .jpeg);Text("\(Int(model.jpegQuality*100))%")};HStack{Text("Dimensão máxima");Slider(value:$model.maxDimension,in:0...4096,step:128).frame(maxWidth:220);Text(model.maxDimension==0 ? "Original":"\(Int(model.maxDimension)) px");Spacer();Button("Pasta de saída…"){model.chooseOutputFolder()};Text(model.outputFolder.lastPathComponent).foregroundStyle(.secondary).lineLimit(1)}}.padding(.top,6)};VStack(alignment:.leading,spacing:8){HStack{Text("Fila de conversão").font(.headline);Text("\(model.files.count)").font(.caption.monospacedDigit()).padding(.horizontal,7).padding(.vertical,3).background(.quaternary,in:Capsule());Spacer();Button("Limpar"){model.clear()}.disabled(model.files.isEmpty||model.isConverting)};if model.files.isEmpty{ContentUnavailableView("Nenhuma imagem adicionada",systemImage:"photo.on.rectangle.angled",description:Text("Adicione uma ou mais imagens para preparar a conversão."))}else{List{ForEach(model.files){item in HStack{Image(nsImage:NSImage(contentsOf:item.url) ?? NSImage(size:NSSize(width:32,height:32))).resizable().scaledToFit().frame(width:36,height:36).clipShape(RoundedRectangle(cornerRadius:5));VStack(alignment:.leading){Text(item.url.lastPathComponent).lineLimit(1);Text(item.status).font(.caption).foregroundStyle(.secondary)};Spacer()}}}.listStyle(.inset)}}.frame(maxHeight:.infinity);HStack{Text(model.message).foregroundStyle(.secondary);Spacer();Button{model.convertAll()}label:{if model.isConverting{ProgressView().controlSize(.small);Text("Convertendo…")}else{Label("Converter arquivos",systemImage:"arrow.right.circle.fill")}}.buttonStyle(.borderedProminent).disabled(model.files.isEmpty||model.isConverting)}}.padding(24).background(Color(nsColor:.windowBackgroundColor)).frame(minWidth:760,minHeight:620)}}
